package httpx

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"gorm.io/gorm"

	"github.com/luiscadari/bancada-api/internal/platform/actor"
	"github.com/luiscadari/bancada-api/internal/platform/apperr"
	"github.com/luiscadari/bancada-api/internal/platform/auth"
	"github.com/luiscadari/bancada-api/internal/platform/database"
)

// StrictHandlerFunc and StrictMiddlewareFunc mirror the aliases generated by oapi-codegen.
type (
	StrictHandlerFunc    = func(ctx *gin.Context, request any) (any, error)
	StrictMiddlewareFunc = func(f StrictHandlerFunc, operationID string) StrictHandlerFunc
)

// Operation describes how an operation is protected.
type Operation struct {
	// Public operations run without a token and without a tenant transaction.
	Public bool
	// Branch operations require the X-Branch-ID header.
	Branch bool
	// Roles allowed to call the operation. Empty means nobody (fail closed).
	Roles []string
}

// Policies maps operation IDs (case-insensitive) to their protection.
type Policies map[string]Operation

func (p Policies) Lookup(operationID string) (Operation, bool) {
	op, ok := p[strings.ToLower(operationID)]
	return op, ok
}

// PrincipalLoader loads the current grants of a user. It runs inside the tenant
// transaction and must fail with an Unauthorized error when the user is disabled or the
// device has been revoked.
type PrincipalLoader interface {
	LoadGrants(ctx context.Context, userID uuid.UUID, deviceID *uuid.UUID) ([]actor.Grant, error)
	BranchExists(ctx context.Context, branchID uuid.UUID) (bool, error)
}

// TenancyMiddleware authenticates the bearer token, opens the tenant transaction
// (RLS, ADR-01), loads the actor, enforces the role policy of the operation and commits
// or rolls back before the response is written.
func TenancyMiddleware(db *gorm.DB, issuer *auth.Issuer, loader PrincipalLoader, policies Policies) StrictMiddlewareFunc {
	return func(next StrictHandlerFunc, operationID string) StrictHandlerFunc {
		return func(c *gin.Context, request any) (any, error) {
			op, known := policies.Lookup(operationID)
			if !known {
				return nil, fmt.Errorf("no policy for operation %s", operationID)
			}
			if op.Public {
				return next(c, request)
			}
			claims, err := bearerClaims(c, issuer)
			if err != nil {
				return nil, err
			}
			userID, _ := claims.UserID()
			a := &actor.Actor{
				AccountID: claims.AccountID,
				UserID:    userID,
				DeviceID:  claims.DeviceID,
				IP:        c.ClientIP(),
				RequestID: RequestID(c),
			}

			var response any
			err = database.TenantTx(c.Request.Context(), db, a.AccountID, func(ctx context.Context) error {
				ctx = actor.With(ctx, a)
				grants, err := loader.LoadGrants(ctx, a.UserID, a.DeviceID)
				if err != nil {
					return err
				}
				a.Grants = grants
				if err := resolveBranch(ctx, c, a, op, loader); err != nil {
					return err
				}
				if !a.HasAnyRole(op.Roles...) {
					return apperr.ErrForbidden
				}
				c.Request = c.Request.WithContext(ctx)
				response, err = next(c, request)
				return err
			})
			if err != nil {
				return nil, err
			}
			return response, nil
		}
	}
}

func bearerClaims(c *gin.Context, issuer *auth.Issuer) (*auth.Claims, error) {
	header := c.GetHeader("Authorization")
	token, ok := strings.CutPrefix(header, "Bearer ")
	if !ok || token == "" {
		return nil, apperr.ErrUnauthenticated
	}
	claims, err := issuer.Parse(token)
	if err != nil {
		slog.DebugContext(c.Request.Context(), "invalid token", "error", err)
		return nil, apperr.Unauthorized("invalid_token", "Sua sessão expirou. Entre novamente.")
	}
	return claims, nil
}

func resolveBranch(ctx context.Context, c *gin.Context, a *actor.Actor, op Operation, loader PrincipalLoader) error {
	raw := c.GetHeader("X-Branch-ID")
	if raw == "" {
		if op.Branch {
			return apperr.Validation("Escolha a filial em que você está trabalhando.",
				apperr.Field("X-Branch-ID", "obrigatório"))
		}
		return nil
	}
	branchID, err := uuid.Parse(raw)
	if err != nil {
		return apperr.Validation("Filial inválida.", apperr.Field("X-Branch-ID", "deve ser um UUID"))
	}
	exists, err := loader.BranchExists(ctx, branchID)
	if err != nil {
		return err
	}
	if !exists || !a.CanAccessBranch(branchID) {
		return apperr.Forbidden("branch_forbidden", "Você não tem acesso a esta filial.")
	}
	a.BranchID = &branchID
	return nil
}

// ErrorHandlers returns the handlers that render strict-server errors as problem+json.
func HandlerError(c *gin.Context, err error) { WriteError(c, err) }

func RequestError(c *gin.Context, err error) {
	WriteError(c, apperr.Validation("Não foi possível ler os dados enviados.", apperr.Field("body", err.Error())))
}

func ResponseError(c *gin.Context, err error) {
	WriteError(c, errors.Join(errors.New("response encoding"), err))
}
